import csv
import hashlib
import io
import os
from pathlib import Path
import zipfile

def parse_orders(csv_text: str) -> list[dict]:
    header = ['prescription_id', 'patient', 'drug', 'quantity', 'status', 'priority']
    try:
        rows = list(csv.reader(io.StringIO(csv_text, newline='')))
    except (csv.Error, TypeError):
        raise ValueError('invalid CSV')
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        pid, patient, drug, quantity, status, priority = [x.strip() for x in row]
        if not pid or not patient or (not drug) or (pid in seen):
            raise ValueError('invalid text or duplicate id')
        try:
            quantity = int(quantity)
            priority = int(priority)
        except ValueError:
            raise ValueError('invalid number')
        if quantity <= 0 or not 0 <= priority <= 9 or status not in ('READY', 'PENDING'):
            raise ValueError('invalid value')
        seen.add(pid)
        result.append({'prescription_id': pid, 'patient': patient, 'drug': drug, 'quantity': quantity, 'status': status, 'priority': priority})
    return result

def process_fulfillment_bundle(archive_path: str, output_dir: str) -> list[dict]:
    try:
        z = zipfile.ZipFile(archive_path)
    except (OSError, zipfile.BadZipFile):
        raise ValueError('invalid archive')
    with z:
        names = z.namelist()
        if names.count('orders.csv') != 1 or len(names) != len(set(names)):
            raise ValueError('invalid archive entries')
        try:
            orders = parse_orders(z.read('orders.csv').decode('utf-8'))
        except (KeyError, UnicodeDecodeError):
            raise ValueError('invalid manifest')
        base = Path(output_dir).resolve()
        base.mkdir(parents=True, exist_ok=True)
        answer = []
        for order in orders:
            if order['status'] != 'READY':
                continue
            member = 'documents/' + order['prescription_id'] + '.txt'
            if member not in names:
                raise ValueError('missing document')
            try:
                data = z.read(member)
                data.decode('utf-8')
            except (KeyError, UnicodeDecodeError):
                raise ValueError('invalid document')
            target = (base / member).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('invalid path')
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
            answer.append({'prescription_id': order['prescription_id'], 'patient': order['patient'], 'drug': order['drug'], 'quantity': order['quantity'], 'priority': order['priority'], 'document_path': member, 'sha256': hashlib.sha256(data).hexdigest()})
    answer.sort(key=lambda x: (-x['priority'], x['quantity'], x['prescription_id']))
    return answer

