def write_delivery_note(base_dir: str, relative_name: str, text: str) -> str:
    if not relative_name or Path(relative_name).is_absolute():
        raise ValueError('relative_name must be a non-empty relative path')
    base = Path(base_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('relative_name must stay beneath base_dir')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding='utf-8')
    return str(target)

