import hashlib
import hmac
import json

def build_loyalty_report(records: list[dict], config: dict, page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page_size')
    key = config.get('report_signing_key') if isinstance(config, dict) else None
    if not isinstance(key, str) or not key:
        raise ValueError('missing report_signing_key')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        customer = record.get('customer')
        points = record.get('points')
        category = record.get('category')
        if not isinstance(customer, str) or not customer:
            raise ValueError('invalid record')
        if isinstance(points, bool) or not isinstance(points, int) or points < 0:
            raise ValueError('invalid record')
        if not isinstance(category, str) or not category:
            raise ValueError('invalid record')
        if customer not in totals:
            totals[customer] = [0, 0]
        totals[customer][0] += points
        totals[customer][1] += 1
    ordered = sorted(totals.items(), key=lambda item: (-item[1][0], item[0]))
    start = (page - 1) * page_size
    items = [{'customer': name, 'points': values[0], 'transactions': values[1]} for name, values in ordered[start:start + page_size]]
    result = {'total_customers': len(ordered), 'page': page, 'page_size': page_size, 'items': items}
    payload = json.dumps(result, sort_keys=True, separators=(',', ':')).encode('utf-8')
    result['signature'] = hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return result

