from typing import Optional

def find_appointments(conn: sqlite3.Connection, patient_name: str='', status: Optional[str]=None, sort_by: str='appointment_date') -> list[tuple]:
    allowed = {'id': 'id', 'patient_name': 'patient_name', 'dentist_name': 'dentist_name', 'appointment_date': 'appointment_date', 'status': 'status'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    clauses = []
    values = []
    if patient_name:
        clauses.append('LOWER(patient_name) LIKE LOWER(?)')
        values.append('%' + patient_name + '%')
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    query = 'SELECT id, patient_name, dentist_name, appointment_date, status, reason FROM appointments'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    query += ' ORDER BY ' + allowed[sort_by] + ', id'
    return conn.execute(query, values).fetchall()

