from xml.etree import ElementTree
from datetime import datetime

def summarize_fleet(xml_text: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        root = ElementTree.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'fleet':
        raise ValueError('invalid root')
    rows = []
    seen = set()
    for robot in root.findall('robot'):
        rid = robot.get('id')
        model = robot.get('model')
        if not rid or not model or rid in seen:
            raise ValueError('invalid robot')
        seen.add(rid)
        readings = robot.findall('reading')
        if not readings:
            raise ValueError('robot has no readings')
        values = []
        counts = {}
        latest = None
        for reading in readings:
            time_text = reading.get('time')
            battery_text = reading.get('battery')
            status = reading.get('status')
            if not time_text or not battery_text or (not status):
                raise ValueError('invalid reading')
            try:
                if not time_text.endswith('Z'):
                    raise ValueError
                parsed_time = datetime.fromisoformat(time_text[:-1] + '+00:00')
                battery = float(battery_text)
            except Exception as exc:
                raise ValueError('invalid reading') from exc
            if not 0 <= battery <= 100:
                raise ValueError('invalid battery')
            values.append(battery)
            counts[status] = counts.get(status, 0) + 1
            if latest is None or parsed_time > latest[0]:
                latest = (parsed_time, time_text, battery, status)
        rows.append({'id': rid, 'model': model, 'average_battery': round(sum(values) / len(values), 1), 'latest_battery': latest[2], 'latest_status': latest[3], 'latest_time': latest[1], 'status_counts': {key: counts[key] for key in sorted(counts)}})
    rows.sort(key=lambda row: (-datetime.fromisoformat(row['latest_time'][:-1] + '+00:00').timestamp(), row['id']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

