import csv
import math
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_claim_summary(claims: list[dict], destination: str) -> list[dict]:
    grouped = {}
    for claim in claims:
        if not isinstance(claim, dict):
            raise ValueError('invalid claim')
        for key in ('claim_id', 'policy_id', 'amount', 'status'):
            if key not in claim:
                raise ValueError('invalid claim')
        if not isinstance(claim['claim_id'], str) or not claim['claim_id']:
            raise ValueError('invalid claim')
        if not isinstance(claim['policy_id'], str) or not claim['policy_id']:
            raise ValueError('invalid claim')
        amount = claim['amount']
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise ValueError('invalid claim')
        if not math.isfinite(amount) or amount < 0:
            raise ValueError('invalid claim')
        if claim['status'] not in ('approved', 'denied', 'pending'):
            raise ValueError('invalid claim')
        if claim['status'] == 'approved':
            try:
                value = Decimal(str(amount))
            except InvalidOperation:
                raise ValueError('invalid claim')
            grouped.setdefault(claim['policy_id'], []).append(value)
    rows = []
    quantum = Decimal('0.01')
    for policy_id in sorted(grouped):
        values = grouped[policy_id]
        total = sum(values, Decimal('0')).quantize(quantum, rounding=ROUND_HALF_UP)
        average = (sum(values, Decimal('0')) / len(values)).quantize(quantum, rounding=ROUND_HALF_UP)
        rows.append({'policy_id': policy_id, 'claim_count': len(values), 'total_approved': format(total, '.2f'), 'average_approved': format(average, '.2f')})
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='claim-summary-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=['policy_id', 'claim_count', 'total_approved', 'average_approved'], lineterminator='\n')
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return rows

