from solution import get_employee_goal_summary
from unittest.mock import Mock, patch
import pytest


def test_summary_calculates_counts_and_average():
    response = Mock(status_code=200)
    response.json.return_value = {
        "goals": [
            {"status": "completed", "progress": 100},
            {"status": "in_progress", "progress": 40},
            {"status": "completed", "progress": 75}
        ]
    }
    with patch("solution.requests.get", return_value=response) as get:
        result = get_employee_goal_summary("https://perf.example.com", "e17", "tok")
    assert result == {"total": 3, "completed": 2, "average_progress": 71.67}
    assert get.call_args.args[0] == "https://perf.example.com/api/v1/employees/e17/goals"


def test_request_contains_expected_parameters_and_headers():
    response = Mock(status_code=200)
    response.json.return_value = {"goals": []}
    with patch("solution.requests.get", return_value=response) as get:
        get_employee_goal_summary("https://host.test/", "abc", "secret-token")
    kwargs = get.call_args.kwargs
    assert kwargs["params"] == {"include": "progress"}
    assert kwargs["headers"] == {"Authorization": "Bearer secret-token"}


def test_empty_goals_have_zero_average():
    response = Mock(status_code=200)
    response.json.return_value = {"goals": []}
    with patch("solution.requests.get", return_value=response):
        result = get_employee_goal_summary("https://x.test", "zero", "t")
    assert result == {"total": 0, "completed": 0, "average_progress": 0.0}


def test_trailing_slashes_are_removed_from_base_url():
    response = Mock(status_code=200)
    response.json.return_value = {"goals": [{"status": "planned", "progress": 12.345}]}
    with patch("solution.requests.get", return_value=response) as get:
        result = get_employee_goal_summary("https://x.test///", "42", "t")
    assert get.call_args.args[0] == "https://x.test/api/v1/employees/42/goals"
    assert result["average_progress"] == 12.35


def test_non_success_status_raises_runtime_error():
    response = Mock(status_code=503)
    with patch("solution.requests.get", return_value=response):
        with pytest.raises(RuntimeError, match="Goals request failed with status 503"):
            get_employee_goal_summary("https://x.test", "42", "t")


def test_only_completed_statuses_are_counted():
    response = Mock(status_code=200)
    response.json.return_value = {
        "goals": [
            {"status": "completed", "progress": 10},
            {"status": "Completed", "progress": 20},
            {"status": "cancelled", "progress": 30}
        ]
    }
    with patch("solution.requests.get", return_value=response):
        result = get_employee_goal_summary("https://x.test", "x", "t")
    assert result == {"total": 3, "completed": 1, "average_progress": 20.0}


def test_fractional_average_is_rounded_to_two_places():
    response = Mock(status_code=200)
    response.json.return_value = {
        "goals": [
            {"status": "in_progress", "progress": 10},
            {"status": "in_progress", "progress": 10},
            {"status": "in_progress", "progress": 11}
        ]
    }
    with patch("solution.requests.get", return_value=response):
        result = get_employee_goal_summary("https://x.test", "x", "t")
    assert result["average_progress"] == 10.33

