            raise ValueError('invalid identity')
        if event not in ('filed', 'interview', 'decision'):
            raise ValueError('invalid event')
        date = _date(record['date'])
        if event == 'decision':
            if record.get('outcome') not in ('approved', 'denied'):
                raise ValueError('invalid outcome')
        elif 'outcome' in record:
            raise ValueError('unexpected outcome')
        case = cases.setdefault(case_id, {'applicant': applicant, 'filed': [], 'interviews': [], 'decision': None})
        if case['applicant'] != applicant:
            raise ValueError('conflicting applicant')
        if event == 'filed':
            case['filed'].append(date)
        elif event == 'interview':
            case['interviews'].append(date)
        else:
