        outcome = decision[1] if decision else None
        result.append({'case_id': case_id, 'applicant': case['applicant'], 'filed_date': filed.isoformat(), 'interview_count': len(case['interviews']), 'decision_date': decision_date, 'outcome': outcome, 'days_to_decision': (decision[0] - filed).days if decision else None, 'status': outcome or 'pending'})
