def rank_log_files(paths: list[str], pattern: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(paths, list):
        raise TypeError('paths must be a list')
    if not isinstance(pattern, str):
        raise TypeError('pattern must be a string')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
