import html

def _fields(line: str) -> list[str]:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_inventory(text: str) -> list[dict[str, object]]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 4:
            raise ValueError('expected four fields')
        name, category = (fields[0].strip(), fields[1].strip())
        if not name or not category:
            raise ValueError('empty field')
        try:
            quantity = int(fields[2].strip())
            value = float(fields[3].strip())
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if quantity < 0 or value < 0:
            raise ValueError('negative number')
        result.append({'name': name, 'category': category, 'quantity': quantity, 'unit_value': value})
    return result

def summarize_inventory(records: list[dict[str, object]]) -> list[dict[str, object]]:
    grouped = {}
    for record in records:
        category = record['category']
        if category not in grouped:
            grouped[category] = {'category': category, 'item_count': 0, 'total_quantity': 0, 'total_value': 0.0}
        row = grouped[category]
        row['item_count'] += 1
        row['total_quantity'] += record['quantity']
        row['total_value'] += record['quantity'] * record['unit_value']
    return sorted(grouped.values(), key=lambda x: (x['category'].casefold(), x['category']))

def render_inventory(records: list[dict[str, object]], title: str) -> str:
    esc = lambda value: html.escape(str(value), quote=True)
    ordered = sorted(records, key=lambda x: (x['category'].casefold(), x['name'].casefold(), x['category'], x['name']))
    rows = ''.join((f"<tr><td>{esc(r['category'])}</td><td>{esc(r['name'])}</td><td>{r['quantity']}</td><td>{r['unit_value']:.2f}</td></tr>" for r in ordered))
    summary = ''.join((f"<li><strong>{esc(r['category'])}</strong>: {r['item_count']} items, {r['total_quantity']} units, {r['total_value']:.2f}</li>" for r in summarize_inventory(records)))
    return f'<div class="inventory"><h1>{esc(title)}</h1><table><thead><tr><th>Category</th><th>Item</th><th>Quantity</th><th>Value</th></tr></thead><tbody>{rows}</tbody><h2>Totals</h2><ul>{summary}</ul></div>'

