import hashlib
import hmac
import os

def _encode(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def _check(password, stored):
    if not isinstance(stored, str) or not isinstance(password, str):
        return False
    try:
        salt_hex, digest_hex = stored.split(':', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, UnicodeError):
        return False

def register_licensees(records: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(records, list) or page < 1 or page_size < 1:
        raise ValueError()
    required = ['name', 'license_number', 'category', 'status', 'score', 'password']
    active = []
    for record in records:
        if not isinstance(record, dict) or any((k not in record for k in required)):
            raise ValueError()
        if any((not isinstance(record[k], str) for k in required if k != 'score')):
            raise ValueError()
        if not isinstance(record['score'], int) or not 0 <= record['score'] <= 100:
            raise ValueError()
        if record['status'] == 'active':
            active.append(record)
    active.sort(key=lambda r: (-r['score'], r['name'].casefold(), r['license_number']))
    start = (page - 1) * page_size
    return [{'name': r['name'], 'license_number': r['license_number'], 'category': r['category'], 'score': r['score'], 'password_hash': _encode(r['password'])} for r in active[start:start + page_size]]

def verify_licensee(account: dict, password: str) -> bool:
    if not isinstance(account, dict):
        return False
    return _check(password, account.get('password_hash'))

