    parameters: list[object] = [min_duration]
    if athlete_ids is not None:
        marks = ','.join(('?' for _ in athlete_ids))
        conditions.append(f'athlete IN ({marks})')
        parameters.extend(athlete_ids)
    where = ' AND '.join(conditions)
    query = f'SELECT athlete, COUNT(*) AS workouts, SUM(duration) AS total_duration, SUM(calories) AS total_calories, ROUND(AVG(duration), 2) AS average_duration FROM workouts WHERE {where} GROUP BY athlete ORDER BY {valid_sorts[sort_by]} DESC, athlete ASC LIMIT ? OFFSET ?'
