import math
import requests

def fetch_listings(endpoint: str, seller_id: str, minimum_price: float=0.0) -> list[dict]:
    if isinstance(minimum_price, bool) or not math.isfinite(float(minimum_price)) or float(minimum_price) < 0:
        raise ValueError('invalid minimum price')
    response = requests.get(endpoint, params={'seller_id': seller_id, 'min_price': minimum_price}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise ValueError(f'unexpected status {response.status_code}')
    try:
        payload = response.json()
        raw_items = payload['items']
        if not isinstance(raw_items, list):
            raise ValueError
        result = []
        for raw in raw_items:
            if not isinstance(raw, dict):
                raise ValueError
            title = str(raw['title']).strip()
            currency = str(raw['currency']).strip()
            category = str(raw['category']).strip()
            price = float(raw['price'])
            rating = float(raw['rating'])
            quantity = int(raw['quantity'])
            sold = int(raw['sold'])
            if not math.isfinite(price) or price < 0 or (not math.isfinite(rating)) or (not 0 <= rating <= 5) or (quantity < 0) or (sold < 0):
                raise ValueError
            result.append({'id': str(raw['id']), 'title': title, 'price': price, 'currency': currency, 'category': category, 'quantity': quantity, 'rating': rating, 'sold': sold})
        return result
    except (KeyError, TypeError, ValueError, OverflowError):
        raise ValueError('invalid listing payload')

def select_listings(listings: list[dict], categories: set[str] | None=None, limit: int | None=None) -> list[dict]:
    if limit is not None and (isinstance(limit, bool) or not isinstance(limit, int) or limit < 0):
        raise ValueError('invalid limit')
    wanted = None if categories is None else {str(x).strip().lower() for x in categories}
    chosen = [x for x in listings if x.get('quantity', 0) > 0 and (wanted is None or str(x.get('category', '')).strip().lower() in wanted)]
    chosen.sort(key=lambda x: (x['price'], -x['rating'], str(x['id'])))
    return chosen if limit is None else chosen[:limit]

def summarize_sales(listings: list[dict]) -> dict[str, dict[str, float | int]]:
    groups = {}
    for item in listings:
        try:
            spelling = str(item['currency']).strip()
            key = spelling.lower()
            price = float(item['price'])
            sold = int(item['sold'])
            if not spelling or not math.isfinite(price) or sold < 0:
                raise ValueError
        except (KeyError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid sale')
        if key not in groups:
            groups[key] = [spelling, 0, 0.0]
        groups[key][1] += sold
        groups[key][2] += price * sold
    return {v[0]: {'units': v[1], 'revenue': round(v[2], 3), 'average_price': round(v[2] / v[1], 2) if v[1] else 0.0} for v in groups.values()}

