import csv
import io
import re
import secrets
_FIELDS = ['accession', 'title', 'artist', 'year', 'location', 'condition']
_CONDITIONS = ('excellent', 'good', 'fair', 'poor')
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def parse_catalog(text: str) -> list[dict]:
    if not text or not text.strip():
        raise ValueError('empty catalog')
    rows = list(csv.reader(io.StringIO(text), delimiter='|', quotechar='"'))
    rows = [row for row in rows if any((part.strip() for part in row))]
    if not rows or [x.strip() for x in rows[0]] != _FIELDS:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        values = [x.strip() for x in row]
        accession, title, artist, year_text, location, condition = values
        if not re.fullmatch('[A-Z]+-[0-9]+', accession):
            raise ValueError('invalid accession')
        if accession in seen or not title or (not artist) or (not location):
            raise ValueError('invalid record')
        try:
            year = int(year_text)
        except ValueError as exc:
            raise ValueError('invalid year') from exc
        if not 1000 <= year <= 2100 or condition not in _CONDITIONS:
            raise ValueError('invalid value')
        seen.add(accession)
        result.append({'accession': accession, 'title': title, 'artist': artist, 'year': year, 'location': location, 'condition': condition})
    return result

def summarize_catalog(records: list[dict]) -> dict[str, dict]:
    grouped = {}
    for record in records:
        location = record['location']
        if location not in grouped:
            grouped[location] = {'count': 0, 'earliest_year': record['year'], 'latest_year': record['year'], 'conditions': {x: 0 for x in _CONDITIONS}}
        item = grouped[location]
        item['count'] += 1
        item['earliest_year'] = min(item['earliest_year'], record['year'])
        item['latest_year'] = max(item['latest_year'], record['year'])
        item['conditions'][record['condition']] += 1
    return {key: grouped[key] for key in sorted(grouped)}

def generate_invite_code(prefix: str='MUS', size: int=10) -> str:
    if not re.fullmatch('[A-Z]{2,8}', prefix) or not isinstance(size, int) or isinstance(size, bool) or (not 6 <= size <= 32):
        raise ValueError('invalid code arguments')
    return prefix + '-' + ''.join((secrets.choice(_ALPHABET) for _ in range(size)))

