def create_invitation(course_id: str, duration_days: int=7) -> dict[str, object]:
    if not isinstance(course_id, str):
        raise TypeError('course_id must be a string')
    course_id = course_id.strip()
    if not course_id:
        raise ValueError('course_id must not be empty')
    if isinstance(duration_days, bool) or not isinstance(duration_days, int):
        raise TypeError('duration_days must be an integer')
    if not 1 <= duration_days <= 30:
        raise ValueError('duration_days must be between 1 and 30')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(10)))
    return {'course_id': course_id, 'code': code, 'duration_days': duration_days, 'uses_remaining': 1}

