import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _money(value):
    try:
        number = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid amount')
    if not number.is_finite():
        raise ValueError('invalid amount')
    return number

def transform_csv(data: str, group_fields: list[str], amount_field: str) -> str:
    if not isinstance(data, str) or len(set(group_fields)) != len(group_fields):
        raise ValueError('invalid arguments')
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='') as staged:
            staged.write(data)
        with open(path, 'r', newline='') as source:
            rows = list(csv.reader(source))
        if not rows:
            headers = list(group_fields) + ['count', 'total', 'average']
            out = __import__('io').StringIO(newline='')
            csv.writer(out, lineterminator='\n').writerow(headers)
            return out.getvalue()
        headers = rows[0]
        if len(headers) != len(set(headers)) or any((not isinstance(x, str) for x in headers)):
            raise ValueError('invalid header')
        if any((x not in headers for x in group_fields)) or amount_field not in headers:
            raise ValueError('unknown column')
        indexes = [headers.index(x) for x in group_fields]
        amount_index = headers.index(amount_field)
        groups = {}
        for row in rows[1:]:
            if len(row) != len(headers):
                raise ValueError('invalid row')
            key = tuple((row[i] for i in indexes))
            amount = _money(row[amount_index])
            if key not in groups:
                groups[key] = [0, Decimal('0')]
            groups[key][0] += 1
            groups[key][1] += amount
        output = __import__('io').StringIO(newline='')
        writer = csv.writer(output, lineterminator='\n')
        writer.writerow(list(group_fields) + ['count', 'total', 'average'])
        for key in sorted(groups):
            count, total = groups[key]
            total_text = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            average = (total / count).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            writer.writerow(list(key) + [str(count), format(total_text, 'f'), format(average, 'f')])
        return output.getvalue()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

